// rut.ts 5.1 (optional; docs-only first)
// No change to ValidateOptions, validate(), or isValidRut().

/**
 * RUTs the SII designates as generic: one number shared by many unrelated
 * parties, so never an identity.
 * Primary sources:
 *  - Formato Boletas v4.2 (2025-09-08), RUTRecep
 *  - Formato DTE, RUTRecep (exportación / TipoFactEsp=1)
 *  - SII FAQ 001_120_3748 (BHE to foreigners)
 * The SII's own RUT (60803000-K) is NOT generic and is deliberately absent.
 */
export const GENERIC_RUTS = Object.freeze({
  /** "RUT genérico": receiver without RUT or internal code (boletas de ventas y servicios; not allowed above 135 UF since 2025-09-01). */
  UNKNOWN: '66666666-6',
  /** "Extranjero sin RUT": export DTEs 110/111/112, factura especial turista (TipoFactEsp=1), other SII forms. */
  FOREIGN: '55555555-5',
  /** Foreign recipient without domicile or residence in Chile, for boletas de honorarios electrónicas. */
  FOREIGN_FEES: '44444446-0',
} as const)

export type GenericRut = (typeof GENERIC_RUTS)[keyof typeof GENERIC_RUTS]

/**
 * True iff `rut` passes validate() (canonical shape, no leading zeros,
 * 64-char cap, Modulo 11) AND its body is a GENERIC_RUTS body.
 * Never throws; false for non-strings.
 */
export const isGenericRut = (rut: unknown): boolean => {
  const d = parseRutLike(rut)
  return d !== null && GENERIC_BODIES.includes(d.body) && isValidDecomposed(d)
}
// internal: const GENERIC_BODIES = ['66666666', '55555555', '44444446']

// README recipes (Security & correctness → "Generic SII RUTs"):
// Accept generic receivers under strict mode (e.g. DTE reception):
//   validate(x, { strict: true }) || isGenericRut(x)
//   This is safe because isGenericRut implies validate(x).
// Identity gate that refuses non-identities:
//   validate(x, { strict: true }) && !isGenericRut(x)
// UNIQUE keys / dedup: skip values where isGenericRut(x) is true.

// dte-sdk (not rut.ts):
//   export const SII_RUT = '60803000-K'  // RutReceptor in EnvioDTE/EnvioBOLETA carátula
//   plus the boleta rules: RUTRecep '0' + CdgIntRecep, the 135 UF real-RUT rule, IndServicio restrictions.

// Rejected outright:
//   validate(rut, { strict: true, allowSiiPlaceholders: true })
//   validate(rut, { strict: 'sii' })
//   a shape-agnostic isSiiPlaceholder()

// --- Ship (5.x minor) ---
/** Holder-type hint for generated fixtures. A numbering convention, never a legal classification. */
export type GenerateKind = 'individual' | 'entity'

export type GenerateOptions = {            // stays a FLAT object type (no union → no type-level break)
  bodyLength?: 7 | 8                        // remains the sole authority on length; default 8
  format?: GenerateFormat
  count?: number
  /**
   * 'individual' → RUN-like body below 50.000.000:
   *     bodyLength 8 (default) → 10.000.000–49.999.999; bodyLength 7 → 1.000.000–9.999.999.
   * 'entity' → body 50.000.000–99.999.999 (the range SII typically uses for legal entities).
   *     Implies an 8-digit body; combining it with bodyLength: 7 throws RangeError.
   * Omitted → exactly today's behaviour (10.000.000–99.999.999 / 1.000.000–9.999.999).
   * Crypto randomness, unbiased sampling and repeated-digit exclusion apply unchanged;
   * if #44 lands, SII_RUT values are also never emitted.
   */
  kind?: GenerateKind
}
function generate(options: GenerateOptions & { count: number }): string[]
function generate(options?: Omit<GenerateOptions, 'count'>): string
// Runtime: kind not in {undefined,'individual','entity'} OR (kind==='entity' && bodyLength===7)
//   → throw new RangeError('Invalid generate options')   // static message, no input echo
// Threshold stays an internal const (e.g. ENTITY_MIN_BODY = 50_000_000), not exported.

// --- Docs only (README, under "Security & correctness" or a new "Person or entity?" note) ---
// Heuristic, not a rule. RUN numbers from Registro Civil are ~28M (2025); SII usually numbers legal
// entities in the 60–99M blocks. Known exceptions: SII gave foreign legal-entity investors
// 47.xxx.xxx, entes sin personalidad jurídica 46.xxx.xxx, sucesiones may use the deceased's RUN,
// and placeholders like 66.666.666-6 (anonymous consumers) sit above 50M.
// Use only for UI hints or analytics, never to accept, reject or decide tax treatment.
const looksLikeEntity = (rut: Rut): boolean => Number(getBody(rut)) >= 50_000_000

// --- Not now (revisit only on demonstrated demand, like parse()) ---
// If ever added: guessHolderKind(rut: unknown): GenerateKind | null
//   null unless validate(rut) (canonical shape + Modulo 11) and !isSiiPlaceholder(rut) (#44);
//   name must signal a guess; English values; JSDoc @remarks stating the counterexamples above.

```ts
/** A RUT found inside free text. */
export type RutMatch = {
  /** Normalized compact RUT, the same form clean() returns: digits + uppercase verifier, e.g. '123456785'. */
  rut: string
  /** UTF-16 offset of the match's first character (inclusive). */
  start: number
  /** UTF-16 offset just past the match (exclusive): text.slice(start, end) is the raw spelling. */
  end: number
}
export type ExtractOptions = {
  /** Default true: only Modulo-11-valid RUTs. false: every RUT-shaped run (e.g. PII redaction, where typos are still PII). */
  requireValid?: boolean
}
export const extract = (text: string, options?: ExtractOptions): RutMatch[]
```
Semantics (normative, document in the README under a new 'Finding RUTs in free text' section):
- Grammar: dotted `[1-9]\d?\.\d{3}\.\d{3}` or hyphen-form `[1-9]\d{6,7}`, then a dash, then `[0-9kK]`. Dash = '-', U+2010, U+2011, U+2012, U+2013 or U+2212. Compact (no-dash) runs are never matched. Bodies are always 7-8 digits with no leading zero, the same bodies validate() accepts.
- Left boundary: start of text, or a char that is not [0-9A-Za-z], '.' or a dash. Right boundary: end of text, or a char that is not [0-9A-Za-z] or a dash, and not '.' followed by a digit. Whitespace, punctuation, '_', '/', '=', '@', '°', 'º', non-ASCII letters and HTML tag characters are all boundaries.
- Output: document order, non-overlapping, duplicates kept. With requireValid (the default), every `rut` satisfies validate(rut) === true.
- Non-string input returns []. Never throws. No size cap: guaranteed O(n), tested on 16 MiB adversarial input.
- Implementation: `for (const m of text.matchAll(RUT_IN_TEXT))` over a private module-level /g regex. The left boundary is emulated with a consumed capture group: start = m.index + m[1].length, end = m.index + m[0].length. No lookbehind, no 'd' flag, verifier computed with calculateVerifierForBody. The in-text regex stays private: it cannot be exported as a #47-style pattern string, because the consumed group makes offsets wrong for consumers.
- Compose instead of adding options: unique -> `[...new Set(extract(t).map(m => m.rut))]`; strict -> `.filter(m => validate(m.rut, { strict: true }))`; display -> `format(m.rut)`; redaction -> `for (const m of extract(t, { requireValid: false }).reverse()) t = t.slice(0, m.start) + mask(m.rut) + t.slice(m.end)`.
- Keep `rut: string`, not the branded `Rut`, so isValidRut() stays the only way to mint a Rut (src/index.ts:15-18).
- Separate docs-only patch now: correct the clean() JSDoc (src/index.ts:219-223), llms.txt:7 and README's 'Ingesting dirty input' section to say clean() takes one value per string, and to use extract() (once shipped) for text.
Prototype: /tmp/claude-0/-home-user-dte-sdk/fc9ade2f-319c-5a08-b848-6a95c60c3cdb/scratchpad/agents/issue46/final.mjs (TS version measured: /tmp/claude-0/-home-user-dte-sdk/fc9ade2f-319c-5a08-b848-6a95c60c3cdb/scratchpad/agents/issue46/build/recMin.ts).

```ts
/**
 * Regex SOURCE strings for the RUT shape contract, mirroring isRutLike() exactly,
 * minus trimming and the 64-char cap: for any s with 1 <= s.length <= 64,
 *   isRutLike(s) === new RegExp(RUT_PATTERN.any).test(s.trim())
 * SHAPE ONLY: no Modulo 11 and no strict check. Always pair with validate() at runtime.
 * Anchored (^...$), flagless, ASCII-only [0-9], zero backslashes, and limited to the
 * JSON Schema interoperable regex subset (JSON Schema/OpenAPI `pattern`, HTML pattern, SQL).
 * Lowercase k is accepted, as in validate(). XSD: strip the anchors (p.slice(1, -1)).
 */
type RutPatterns = {
  /** Any accepted shape: compact, hyphen or dotted. */
  readonly any: string
  /** '123456785' */
  readonly compact: string
  /** '12345678-5' */
  readonly hyphen: string
  /** '12.345.678-5', '1.234.567-4' */
  readonly dotted: string
}

const COMPACT_HYPHEN = '[1-9][0-9]{6,7}-?[0-9kK]'                      // internal fragments,
const DOTTED_SRC = '[1-9][0-9]?[.][0-9]{3}[.][0-9]{3}-[0-9kK]'         // reusable by #46 extract()

export const RUT_PATTERN: RutPatterns = Object.freeze({
  any: '^([1-9][0-9]{6,7}-?[0-9kK]|[1-9][0-9]?[.][0-9]{3}[.][0-9]{3}-[0-9kK])$',
  compact: '^[1-9][0-9]{6,7}[0-9kK]$',
  hyphen: '^[1-9][0-9]{6,7}-[0-9kK]$',
  dotted: '^[1-9][0-9]?[.][0-9]{3}[.][0-9]{3}-[0-9kK]$',
})
export type { RutPatterns }

// Internals: single source of truth (removes 3 regex literals)
const SHAPE = new RegExp(RUT_PATTERN.any)
// parseRutLike: if (!SHAPE.test(input)) return null
// The leading-zero guard becomes redundant ([1-9] is now load-bearing): either
// keep it as defense in depth (mark the equivalent mutant for Stryker) or remove
// it and let the exhaustive test plus the differential harness prove no change.
```
Semantics and decisions:
- Strings, not RegExp objects: portable, immutable primitives, serializable, and no lastIndex/flag state.
- Use explicit `string` member types (not `as const` literals), so the d.ts does not freeze the exact spelling of each regex.
- Do NOT export RUT_JSON_SCHEMA; document the one-liner `{ type: 'string', pattern: RUT_PATTERN.any, minLength: 8, maxLength: 12 }`.
- Do NOT export an SII/XSD pattern; dte-sdk mirrors SiiTypes RUTType `[0-9]+-([0-9]|K)` exactly.
- README section 'Schema patterns (JSON Schema / OpenAPI / SQL)', placed beside the accepted-formats table:
  - Shape only.
  - Zod: `z.string().trim().regex(new RegExp(RUT_PATTERN.any)).refine(validate)` (the regex survives z.toJSONSchema, the refine does not).
  - PostgreSQL storage: `CHECK (rut ~ '<RUT_PATTERN.compact>' AND rut = upper(rut))` on clean() output.
  - Engine notes: Python use fullmatch, PHP /D, Ruby \A\z, XSD strip anchors, never add g/y.
  - Patterns describe the default 7-8 digit, non-strict contract.
- Tests:
  - Exhaustive equivalence over alphabet '01K.-' up to length 10 (~12M strings, a few seconds).
  - fast-check property using mutated generate() output and Unicode whitespace/digits.
  - Each string compiles under '', 'u' and 'v' and inside the HTML wrapping.
  - No string contains a backslash.
  - Object is frozen.
  - Update the dist smoke test (non-function export) and the expect-type tests.

